/** Markdown overview of the whole structure for AI tools; pure rendering, no Obsidian access. */
import { child_entries, describe_note, type StructureIndex, type TreeEntry } from './structure_index';

/** Vault path of the generated file; a dot folder is neither indexed by Obsidian nor synced by Obsidian Sync. */
export const STRUCTURE_EXPORT_PATH = '.moc-tree/structure.md';

/** Settings the explanation needs. */
export interface ExportContext {
	/** Managed folders; `''` stands for the whole vault. */
	folders: readonly string[];
	structure_key: string;
	trash_tag: string;
}

/** Inline code span that survives backticks in the text. */
function code(text: string): string {
	return text.includes('`') ? `\`\` ${text} \`\`` : `\`${text}\``;
}

/** Text safe for one table cell. */
function cell(text: string): string {
	return text.replace(/\|/g, '\\|').replace(/\s*\n\s*/g, ' ');
}

/** Explanation of the note format, so the file is readable without knowing the plugin. */
function render_intro(ctx: ExportContext): string[] {
	const folders = ctx.folders.map((folder) => (folder === '' ? '(whole vault)' : code(folder))).join(', ');
	const key = code(ctx.structure_key);
	return [
		'# MOC Tree structure',
		'',
		'Generated by the Obsidian plugin MOC Tree from the notes\' frontmatter and rewritten whenever the',
		'structure changes. Do not edit this file; the notes themselves are the only source of truth.',
		'',
		'## How the notes are organized',
		'',
		`- Managed folders (recursive): ${folders}. Every Markdown note there is a managed note.`,
		'- Each note has a `title` (its display name) and `aliases` (title plus synonyms). File names are',
		'  usually timestamps without meaning. A link like `[[2026111009123048]]` points to a file name;',
		'  look up its title in the table "Notes" below.',
		`- A note with the property ${key} is a folder note (MOC). ${key} lists its entries in order,`,
		'  one wiki link per line. Folders contain notes and further folders; a note can be in several',
		'  folders. There are no real directories for this structure.',
		`- Links in the note text are cross-references, never structure. Only ${key} defines the tree.`,
		`- Notes tagged ${code(`#${ctx.trash_tag}`)} are in the trash; they keep their place in ${key}.`,
		'- Notes outside the managed folders appear only if a folder note links them.',
		'',
	];
}

/** Explanation above the tree. */
const TREE_HELP =
	'Indented by depth, in the order of the folder lists. Each line: title — path [markers].\n' +
	'Folder notes are bold; a note in several folders appears in each of them.';

/** Marker suffix for one tree row. */
function markers(entry: TreeEntry): string {
	const parts: string[] = [];
	if (entry.kind === 'moc') parts.push('folder');
	if (entry.kind === 'dead') parts.push('not found');
	if (entry.kind === 'cycle') parts.push('contains itself, not expanded');
	if (entry.outside && entry.kind !== 'dead') parts.push('outside managed folders');
	if (entry.missing_title) parts.push('no title');
	if (entry.parent_count > 1) parts.push(`in ${entry.parent_count} folders`);
	return parts.length > 0 ? ` [${parts.join(', ')}]` : '';
}

/** Renders tree sections; folders expanded once are referenced afterwards to keep the size linear. */
class TreeWriter {
	readonly lines: string[] = [];
	private readonly expanded = new Set<string>();

	constructor(private readonly index: StructureIndex) {}

	/** Write one entry and, for folders, its entries below. */
	entry(entry: TreeEntry, depth: number, chain: readonly string[], in_trash: boolean): void {
		const indent = '  '.repeat(depth);
		const target = entry.path === null ? code(`[[${entry.link}]]`) : code(entry.path);
		const name = entry.kind === 'moc' ? `**${entry.name}**` : entry.name;
		const path = entry.path;
		const repeat = entry.kind === 'moc' && path !== null && this.expanded.has(path);
		const suffix = repeat ? `${markers(entry)} (entries listed above)` : markers(entry);
		this.lines.push(`${indent}- ${name} — ${target}${suffix}`);
		if (entry.kind !== 'moc' || path === null || repeat) return;
		this.expanded.add(path);
		const next = [...chain, path];
		for (const child of child_entries(this.index, path, new Set(next), in_trash)) {
			this.entry(child, depth + 1, next, in_trash);
		}
	}

	/** Write a section with its top-level paths; `empty` is shown if there are none. */
	section(heading: string, help: string, paths: readonly string[], empty: string, in_trash = false): void {
		this.lines.push(`## ${heading}`, '', help, '');
		if (paths.length === 0) this.lines.push(empty);
		for (const path of paths) this.entry(describe_note(this.index, path), 0, [], in_trash);
		this.lines.push('');
	}
}

/** Table of all known notes: file, title, aliases, folders. */
function render_notes(index: StructureIndex): string[] {
	const lines = [
		'## Notes',
		'',
		'All notes the plugin knows, by path. "Folders" lists the file names of the folder notes that',
		'contain the note.',
		'',
		'| File name | Title | Aliases | Folders | Path |',
		'| --- | --- | --- | --- | --- |',
	];
	const notes = [...index.notes.values()].sort((a, b) => a.path.localeCompare(b.path));
	for (const note of notes) {
		const parents = (index.parents.get(note.path) ?? []).map((p) => index.notes.get(p)?.basename ?? p);
		const flags = [note.children ? 'folder' : '', note.trashed ? 'trash' : '', note.managed ? '' : 'outside']
			.filter((flag) => flag !== '')
			.join(', ');
		const title = note.title ?? '(no title)';
		const row = [note.basename, flags ? `${title} [${flags}]` : title, note.aliases.join(', '), parents.join(', '), note.path];
		lines.push(`| ${row.map(cell).join(' | ')} |`);
	}
	lines.push('');
	return lines;
}

/** Complete file content; identical input gives identical output (no timestamps). */
export function render_structure_export(index: StructureIndex, ctx: ExportContext): string {
	const tree = new TreeWriter(index);
	tree.section('Tree', TREE_HELP, index.roots, '(no folder notes yet)');
	tree.section('Orphans', 'Managed notes that are in no folder.', index.orphans, '(none)');
	tree.section('Trash', 'Trashed notes with their entries.', index.trash, '(empty)', true);
	return [...render_intro(ctx), ...tree.lines, ...render_notes(index)].join('\n');
}
